class LegalIn(StrictModel):
    version:StrictInt=Field(ge=0)
    name:str=Field(min_length=3,max_length=200)
    inn:str=Field(pattern=r'^\d{10}(?:\d{2})?$')
    ogrnip:str=Field(pattern=r'^\d{13}(?:\d{2})?$')
    city:str=Field(min_length=2,max_length=200)
    postal_address:str=Field(default='',max_length=500)
    email:str=Field(max_length=254,pattern=r'^[A-Za-z0-9.!#$%&\x27*+/=?^_`{|}~-]+@[A-Za-z0-9](?:[A-Za-z0-9.-]*[A-Za-z0-9])?\.[A-Za-z]{2,}$')
    infrastructure:str=Field(min_length=30,max_length=1500)

def information(db):
    row=db.get(Setting,KEY);saved=parse(row.value) if row else {}
    return {'version':saved.get('version',0),**{k:saved.get(k,v) for k,v in DEFAULTS.items()}}

