def public_data(db):
    info=information(db)
    version=hashlib.sha256((TEXT_VERSION+dump(info)).encode()).hexdigest()[:20]
    return {'version':version,'updated':'2026-11-02','operator':info,'documents':documents(info)}

def archive_version(db,data):
    key='legal_snapshot:'+data['version']
    if not db.get(Setting,key):db.add(Setting(key=key,value=dump(data)))

@router.get('/api/legal')
def public(db=Depends(get_db)):return public_data(db)

@router.get('/api/legal/versions/{version}')
def old_version(version:str,a=Depends(actor),db=Depends(get_db)):
    if version==public_data(db)['version']:return public_data(db)
    require(a.role=='owner' or db.scalar(select(LegalAcceptance.id).where(LegalAcceptance.account_id==a.id,LegalAcceptance.version==version).limit(1)),'Версия недоступна',404)
    row=db.get(Setting,'legal_snapshot:'+version);require(row,'Версия не найдена',404)
    return parse(row.value)

@router.get('/api/legal/acknowledgements')
def acknowledgements(a=Depends(actor),db=Depends(get_db)):
    return [{'document':r.document,'version':r.version,'accepted_at':iso(r.accepted_at)} for r in db.scalars(select(LegalAcceptance).where(LegalAcceptance.account_id==a.id)).all()]

class AcknowledgeIn(StrictModel):
    document:str=Field(max_length=40)
    version:str=Field(max_length=64)

@router.post('/api/legal/acknowledgements')
def acknowledge(body:AcknowledgeIn,a=Depends(actor),db=Depends(get_db)):
    # Legal edits and simultaneous acknowledgements share one lock. Preserve the
    # exact text, not just a hash which could not later be reconstructed.
    db.execute(select(Setting).where(Setting.key==KEY).with_for_update()).first()
    current=public_data(db);require(body.document in current['documents'],'Документ не найден',404)
    require(body.version==current['version'],'Документ изменился. Обновите страницу перед подтверждением.',409)
    archive_version(db,current)
    from .models import Account
    db.execute(select(Account).where(Account.id==a.id).with_for_update()).first()
    row=db.scalar(select(LegalAcceptance).where(LegalAcceptance.account_id==a.id,LegalAcceptance.document==body.document,LegalAcceptance.version==body.version))
    if not row:row=LegalAcceptance(account_id=a.id,document=body.document,version=body.version);db.add(row)
    db.commit();return {'document':row.document,'version':row.version,'accepted_at':iso(row.accepted_at)}

@router.put('/api/owner/legal')
def save(body:LegalIn,a=Depends(actor),db=Depends(get_db)):
    owner(a);row=db.scalar(select(Setting).where(Setting.key==KEY).with_for_update())
    require(row and information(db)['version']==body.version,'Реквизиты уже изменены. Обновите страницу.',409)
    archive_version(db,public_data(db))
    row.value=dump({**body.model_dump(),'version':body.version+1});log(db,a,None,'Обновлена юридическая информация',version=body.version+1);db.commit()
    return public_data(db)
